CREATE TABLE IF NOT EXISTS schema_migrations(version TEXT PRIMARY KEY, applied_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS administrators(id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, admin_id TEXT NOT NULL REFERENCES administrators(id), expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires_at);
CREATE TABLE IF NOT EXISTS login_limits(key_hash TEXT PRIMARY KEY, window_start INTEGER NOT NULL, attempts INTEGER NOT NULL CHECK(attempts >= 0));
CREATE TABLE IF NOT EXISTS menu_categories(id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, sort INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS menu_products(id TEXT PRIMARY KEY, category_id TEXT NOT NULL REFERENCES menu_categories(id), name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS menu_options(id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES menu_products(id), variant TEXT NOT NULL, portion TEXT NOT NULL, pieces INTEGER CHECK(pieces > 0), price INTEGER NOT NULL CHECK(price >= 0), available INTEGER NOT NULL DEFAULT 1 CHECK(available IN (0,1)), sort INTEGER NOT NULL DEFAULT 0, image TEXT NOT NULL DEFAULT 'steam');
CREATE TABLE IF NOT EXISTS daily_sequences(business_date TEXT PRIMARY KEY, sequence INTEGER NOT NULL CHECK(sequence > 0));
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY, business_date TEXT NOT NULL, sequence INTEGER NOT NULL CHECK(sequence > 0), status TEXT NOT NULL CHECK(status IN ('pending','preparing','ready','completed','cancelled')), order_type TEXT NOT NULL CHECK(order_type IN ('takeaway','dine-in')), note TEXT NOT NULL DEFAULT '', subtotal INTEGER NOT NULL CHECK(subtotal >= 0), adjustment INTEGER NOT NULL DEFAULT 0, total INTEGER NOT NULL CHECK(total >= 0 AND total = subtotal + adjustment), collected INTEGER NOT NULL DEFAULT 0 CHECK(collected >= 0 AND collected <= total), payment_method TEXT CHECK(payment_method IN ('cash','upi','other')), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, version INTEGER NOT NULL DEFAULT 1, idempotency_key TEXT NOT NULL UNIQUE, request_hash TEXT NOT NULL, UNIQUE(business_date,sequence), CHECK(collected=0 OR payment_method IS NOT NULL));
CREATE INDEX IF NOT EXISTS order_active ON orders(status,created_at);
CREATE INDEX IF NOT EXISTS order_date ON orders(business_date,sequence);
CREATE TABLE IF NOT EXISTS order_items(id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), option_id TEXT NOT NULL, name TEXT NOT NULL, variant TEXT NOT NULL, portion TEXT NOT NULL, pieces INTEGER, quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 99), unit_price INTEGER NOT NULL CHECK(unit_price >= 0), total INTEGER NOT NULL CHECK(total=quantity*unit_price), note TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS items_order ON order_items(order_id);
CREATE TABLE IF NOT EXISTS display_links(id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE, channel TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL, revoked_at INTEGER);
CREATE TABLE IF NOT EXISTS app_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS order_events(id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), kind TEXT NOT NULL, version INTEGER NOT NULL, created_at INTEGER NOT NULL, detail TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS event_order ON order_events(order_id,created_at);
CREATE TABLE IF NOT EXISTS outbox(id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), version INTEGER NOT NULL, created_at INTEGER NOT NULL, published_at INTEGER, attempts INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS outbox_pending ON outbox(published_at,created_at);
